//! Extension packs provided by a project (`[postgres] packs` in
//! `pgzest.toml`), generated by `pgzest db pack` from the PostgreSQL that
//! has the extension installed.
//!
//! They complete the packs shipped with pgzest ([`crate::builtin`]): a
//! `CREATE EXTENSION` looks its pack up in both, the project's first. A pack
//! that cannot be used is reported, never skipped silently.

use std::path::{Path, PathBuf};

use pgzest_diagnostics::{Diagnostic, codes};

use crate::builtin;
use crate::pack::Pack;

/// Packs of a project, and what was wrong with the ones that are not usable.
#[derive(Debug, Clone, Default)]
pub struct ProjectPacks {
    packs: Vec<(PathBuf, Pack)>,
    /// Diagnostics of the loading, with the file (or directory) concerned.
    pub diagnostics: Vec<(PathBuf, Diagnostic)>,
}

impl ProjectPacks {
    /// Packs of the project configured by `config`, at `root`.
    pub fn for_config(root: &Path, config: &pgzest_schema::ProjectConfig) -> Self {
        Self::load(root, &config.postgres.packs, config.postgres.version)
    }

    /// Errors: packs that are configured but cannot be used.
    pub fn errors(&self) -> impl Iterator<Item = &(PathBuf, Diagnostic)> {
        self.diagnostics
            .iter()
            .filter(|(_, d)| d.severity == pgzest_diagnostics::Severity::Error)
    }

    /// `path` is in one of the pack directories of `config`: a change to it
    /// changes the available packs.
    pub fn is_pack_file(root: &Path, config: &pgzest_schema::ProjectConfig, path: &Path) -> bool {
        path.extension().is_some_and(|x| x == "json")
            && config
                .postgres
                .packs
                .iter()
                .any(|d| path.parent() == Some(root.join(d).as_path()))
    }

    /// Packs of the `dirs` directories (relative to `root`), for PostgreSQL
    /// `postgres`. Every `.json` file of a directory is a pack.
    pub fn load(root: &Path, dirs: &[PathBuf], postgres: u32) -> Self {
        let mut out = ProjectPacks::default();
        for dir in dirs {
            let dir = root.join(dir);
            let entries = match std::fs::read_dir(&dir) {
                Ok(e) => e,
                Err(e) => {
                    out.error(&dir, format!("pack directory unreadable: {e}"));
                    continue;
                }
            };
            let mut files: Vec<PathBuf> = entries
                .filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| p.extension().is_some_and(|x| x == "json"))
                .collect();
            files.sort();
            for file in files {
                match std::fs::read_to_string(&file) {
                    Ok(text) => out.add(&file, &text, postgres),
                    Err(e) => out.error(&file, format!("pack unreadable: {e}")),
                }
            }
        }
        out
    }

    /// Adds the pack read from `file`, if it can be used with PostgreSQL
    /// `postgres`.
    pub fn add(&mut self, file: &Path, text: &str, postgres: u32) {
        let pack = match Pack::from_json(text) {
            Ok(p) => p,
            Err(e) => return self.error(file, e.0),
        };
        let id = pack.contributor.to_string();
        if pack.contributor.name == "postgres" {
            return self.error(
                file,
                format!("{id} is a base catalog, not an extension pack"),
            );
        }
        match pack.postgres.as_deref() {
            Some(v) if v == postgres.to_string() => {}
            Some(v) => {
                return self.error(
                    file,
                    format!(
                        "pack {id} was generated with postgres@{v}, the project targets \
                         postgres@{postgres}: regenerate it with `pgzest db pack` on a \
                         PostgreSQL {postgres} server"
                    ),
                );
            }
            None => {
                return self.error(
                    file,
                    format!(
                        "pack {id} does not say which PostgreSQL version it was generated with"
                    ),
                );
            }
        }
        if let Some((first, _)) = self
            .packs
            .iter()
            .find(|(_, p)| p.contributor == pack.contributor)
        {
            return self.error(
                file,
                format!("pack {id} is already provided by {}", first.display()),
            );
        }
        if builtin::versions(&pack.contributor.name).contains(&pack.contributor.version.as_str()) {
            self.diagnostics.push((
                file.to_path_buf(),
                Diagnostic::info(
                    codes::INVALID_PACK,
                    format!("pack {id} replaces the one shipped with pgzest"),
                ),
            ));
        }
        self.packs.push((file.to_path_buf(), pack));
    }

    fn error(&mut self, file: &Path, message: String) {
        self.diagnostics.push((
            file.to_path_buf(),
            Diagnostic::error(codes::INVALID_PACK, message),
        ));
    }

    /// Versions of `name` the project provides.
    pub fn versions(&self, name: &str) -> Vec<&str> {
        self.packs
            .iter()
            .filter(|(_, p)| p.contributor.name == name)
            .map(|(_, p)| p.contributor.version.as_str())
            .collect()
    }

    /// Pack `name@version` of the project.
    pub fn get(&self, name: &str, version: &str) -> Option<&Pack> {
        self.packs
            .iter()
            .map(|(_, p)| p)
            .find(|p| p.contributor.name == name && p.contributor.version == version)
    }

    /// The project's packs.
    pub fn iter(&self) -> impl Iterator<Item = &Pack> {
        self.packs.iter().map(|(_, p)| p)
    }

    /// Files the packs were read from.
    pub fn files(&self) -> impl Iterator<Item = &Path> {
        self.packs.iter().map(|(f, _)| f.as_path())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pack(name: &str, version: &str, postgres: Option<&str>) -> String {
        let postgres = postgres
            .map(|v| format!("\"postgres\": \"{v}\","))
            .unwrap_or_default();
        format!(
            "{{\"format\": {}, \"contributor\": {{\"name\": \"{name}\", \"version\": \"{version}\"}}, \
             {postgres} \"schemas\": [], \"types\": [], \"routines\": [], \"operators\": [], \
             \"casts\": [], \"opclasses\": [], \"relations\": []}}",
            crate::pack::PACK_FORMAT
        )
    }

    fn messages(p: &ProjectPacks) -> Vec<String> {
        p.diagnostics
            .iter()
            .map(|(_, d)| d.message.clone())
            .collect()
    }

    #[test]
    fn a_pack_for_the_targeted_version_is_provided() {
        let mut p = ProjectPacks::default();
        p.add(Path::new("a.json"), &pack("hstore", "1.8", Some("18")), 18);
        assert!(p.diagnostics.is_empty(), "{:?}", messages(&p));
        assert_eq!(p.versions("hstore"), ["1.8"]);
        assert!(p.get("hstore", "1.8").is_some());
    }

    #[test]
    fn a_pack_for_another_version_is_refused() {
        let mut p = ProjectPacks::default();
        p.add(Path::new("a.json"), &pack("hstore", "1.8", Some("17")), 18);
        p.add(Path::new("b.json"), &pack("ltree", "1.3", None), 18);
        assert!(p.versions("hstore").is_empty());
        assert!(p.versions("ltree").is_empty());
        let m = messages(&p);
        assert!(m[0].contains("generated with postgres@17"), "{m:?}");
        assert!(m[1].contains("does not say"), "{m:?}");
    }

    #[test]
    fn a_duplicate_or_a_base_catalog_is_refused() {
        let mut p = ProjectPacks::default();
        p.add(Path::new("a.json"), &pack("hstore", "1.8", Some("18")), 18);
        p.add(Path::new("b.json"), &pack("hstore", "1.8", Some("18")), 18);
        p.add(Path::new("c.json"), &pack("postgres", "18", Some("18")), 18);
        p.add(Path::new("d.json"), "{", 18);
        let m = messages(&p);
        assert_eq!(m.len(), 3, "{m:?}");
        assert!(m[0].contains("already provided by a.json"), "{m:?}");
        assert!(m[1].contains("base catalog"), "{m:?}");
        assert!(m[2].contains("unreadable pack"), "{m:?}");
    }

    #[test]
    fn replacing_a_shipped_pack_is_said() {
        let mut p = ProjectPacks::default();
        p.add(Path::new("a.json"), &pack("citext", "1.8", Some("18")), 18);
        assert_eq!(p.versions("citext"), ["1.8"]);
        assert_eq!(
            p.diagnostics[0].1.severity,
            pgzest_diagnostics::Severity::Info
        );
    }

    #[test]
    fn a_missing_directory_is_an_error() {
        let p = ProjectPacks::load(Path::new("/nonexistent"), &[PathBuf::from("packs")], 18);
        assert!(messages(&p)[0].contains("pack directory unreadable"));
    }
}
